(() => {
  const out = {};
  const ld = [...document.querySelectorAll('script[type="application/ld+json"]')].map(s => { try { return JSON.parse(s.textContent);} catch(e){return null;} }).filter(Boolean);
  const rec = ld.find(o => JSON.stringify(o['@type']||'').includes('MusicRecording'));
  if (rec) { const r = {...rec}; delete r.author; delete r.additionalProperty; delete r.comment; out.rec = r; }
  const html = document.documentElement.outerHTML;
  out.allAudioish = [...new Set(html.match(/https?:\\?\/\\?\/[^"'\s<>]*(audio_|\.mp3|\.m4a|\.ogg|preview)[^"'\s<>]*/g) || [])].slice(0,30);
  out.audioEls = document.querySelectorAll('audio').length;
  out.perf = performance.getEntriesByType('resource').map(e=>e.name).filter(n=>/audio|mp3|m4a|ogg|download/i.test(n));
  return JSON.stringify(out, null, 1);
})()

